package com.forgeci.domain.repository;
import com.forgeci.domain.organization.Organization; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="repositories",schema="forgeci",uniqueConstraints=@UniqueConstraint(name="uk_repo_external",columnNames={"organization_id","provider","external_id"}))
public class Repository { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="organization_id",nullable=false) private Organization organization; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private RepositoryProvider provider; @Column(name="external_id",nullable=false,length=120) private String externalId; @Column(nullable=false,length=200) private String name; @Column(name="full_name",nullable=false,length=400) private String fullName; @Column(name="clone_url",nullable=false,length=1000) private String cloneUrl; @Column(name="default_branch",nullable=false,length=255) private String defaultBranch; @Column(name="private",nullable=false) private boolean privateRepository; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; protected Repository(){} public Repository(Organization o,RepositoryProvider p,String eid,String name,String fullName,String cloneUrl,String branch,boolean priv){organization=o;provider=p;externalId=eid;this.name=name;this.fullName=fullName;this.cloneUrl=cloneUrl;defaultBranch=branch;privateRepository=priv;} @PrePersist void create(){var n=Instant.now();createdAt=n;updatedAt=n;} @PreUpdate void update(){updatedAt=Instant.now();} public UUID getId(){return id;} public Organization getOrganization(){return organization;} public RepositoryProvider getProvider(){return provider;} public String getExternalId(){return externalId;} public String getName(){return name;} public String getFullName(){return fullName;} public String getCloneUrl(){return cloneUrl;} public String getDefaultBranch(){return defaultBranch;} public boolean isPrivateRepository(){return privateRepository;} public void refresh(String n,String f,String c,String b,boolean p){name=n;fullName=f;cloneUrl=c;defaultBranch=b;privateRepository=p;} }
